const els = {};
const LAST_SAVE_KEY = "nbaGmLastSave";
const TUTORIAL_COMPLETED_KEY = "nbaGmFirstRunTutorialCompleted";
const DASHBOARD_EXPERIENCE_KEY = "nbaGmDashboardExperience";
const MULTIPLAYER_SESSION_KEY = "nbaGmMultiplayerSession";
const BOARD_THEME_KEY = "nbaGmBoardTheme";
// Board background themes (Settings > Board). Slate is the default; the others are kept as choices.
const BOARD_THEMES = [["slate", "Slate blue"], ["charcoal", "Warm charcoal"], ["cream", "Cream paper"]];
function boardTheme() {
  let saved = "";
  try { saved = localStorage.getItem(BOARD_THEME_KEY) || ""; } catch {}
  return BOARD_THEMES.some(([key]) => key === saved) ? saved : "slate";
}
function applyBoardTheme(theme = boardTheme()) {
  document.documentElement.dataset.boardTheme = theme;
}
applyBoardTheme();
// Look choices in Settings (round 4): the glass style and the font. Each is a data attribute on <html>; the CSS in
// glass-clear.css and fonts.css reads it. Rating and role colours depend on the glass, so a change re-renders.
// Round 5: one glass look only (the light Frosted option is gone); the font default is Helvetica Neue.
const UI_LOOK_SETTINGS = {
  glass: { key: "nbaGmGlass", label: "Glass", fallback: "clear", options: [["clear", "Clear"]] },
  font: { key: "nbaGmFont", label: "Font", fallback: "helvetica", options: [["helvetica", "Helvetica Neue"], ["modern", "SF Pro"], ["rounded", "Rounded"], ["avenir", "Avenir Next"], ["classic", "Classic (Tahoma)"]] },
  // Round 6: the user couldn't pick one button style, so all four are offered.
  buttons: { key: "nbaGmButtons", label: "Buttons", fallback: "pill", options: [["pill", "Glass pill"], ["solid", "Solid pill"], ["square", "Rounded square"], ["segmented", "Segmented"]] },
};
const UI_LOOK_DATASET = { glass: "glass", font: "uiFont", buttons: "uiButtons" };
function uiLook(name) {
  const setting = UI_LOOK_SETTINGS[name];
  let saved = "";
  try { saved = localStorage.getItem(setting.key) || ""; } catch {}
  return setting.options.some(([key]) => key === saved) ? saved : setting.fallback;
}
function applyUiLooks() {
  for (const name of Object.keys(UI_LOOK_SETTINGS)) document.documentElement.dataset[UI_LOOK_DATASET[name]] = uiLook(name);
}
function clearGlass() { return document.documentElement.dataset.glass === "clear"; }
applyUiLooks();
