  australia:"AU", brazil:"BR", canada:"CA", china:"CN", croatia:"HR", france:"FR", germany:"DE", greece:"GR",
  italy:"IT", japan:"JP", latvia:"LV", lithuania:"LT", nigeria:"NG", "new-zealand":"NZ", "south-sudan":"SS",
