const PROSPECT_CLUB_COUNTRIES = Object.freeze({
  "kk-mega-basket":"RS", valencia:"ES", "real-madrid":"ES", barcelona:"ES", "fc-barcelona":"ES", "ratiopharm-ulm":"DE",
  "partizan-belgrade":"RS", "crvena-zvezda":"RS", "red-star-belgrade":"RS", "olympiacos":"GR", "panathinaikos":"GR",
  baskonia:"ES", joventut:"ES", "nanterre-92":"FR", "elan-chalon":"FR", "paris-basketball":"FR", asvel:"FR",
  "south-east-melbourne":"AU", "cedevita-olimpija":"SI", zalgiris:"LT", trento:"IT", "mega-basket-okk-beograd":"RS",
  "le-mans":"FR",
});
// Source names written differently from the logo file names ("Ohio St.", "Connecticut").
const PROSPECT_ORIGIN_ALIASES = Object.freeze({connecticut:"uconn"});

function prospectOriginKey(value) {
  // A school's "(City, ST)" or a note in brackets is not part of its name.
  const key = prospectOriginSlug(String(value || "").replace(/\s*\([^)]*\)/g, ""));
  const named = PROSPECT_ORIGIN_ALIASES[key] || key;
  return named.endsWith("-st") && !PROSPECT_COLLEGE_LOGOS[named] ? named.replace(/-st$/, "-state") : named;
}

function prospectOriginSlug(value) {
  return String(value || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/['’]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function prospectFlagEmoji(countryCode) {
  return String.fromCodePoint(...Array.from(countryCode.toUpperCase(), (letter) => letter.charCodeAt(0) + 127397));
}

function prospectOriginMarkup(origin) {
  const label = String(origin || "").trim() || "Source unavailable";
  const key = prospectOriginKey(label);
  const countryCode = PROSPECT_COUNTRY_FLAGS[key] || PROSPECT_CLUB_COUNTRIES[key];
  if (countryCode) {
    return `<span class="season-prospect-origin season-prospect-flag" role="img" aria-label="${escapeAttr(`${label} flag`)}" title="${escapeAttr(label)}">${escapeHtml(prospectFlagEmoji(countryCode))}</span>`;
  }
  const collegeLogo = PROSPECT_COLLEGE_LOGOS[key];
  if (collegeLogo) {
    return `<img class="season-prospect-origin season-prospect-college-logo" src="/assets/team_logos/colleges/${escapeAttr(collegeLogo)}.png" alt="${escapeAttr(`${label} logo`)}" title="${escapeAttr(label)}" loading="lazy" decoding="async" />`;
  }
  const initials = label.split(/\s+/).filter(Boolean).map((part) => part[0]).join("").slice(0, 2).toUpperCase() || "?";
  return `<span class="season-prospect-origin season-prospect-source-fallback" role="img" aria-label="${escapeAttr(label)}" title="${escapeAttr(label)}">${escapeHtml(initials)}</span>`;
}

// Upcoming Prospects table. Columns: [column, [[sort key, header label, header tip], ...]]. The draft-range column holds two sorts
// (league consensus, your scouts). Numbers start high-to-low on the first click; ranks, names and ages low-to-high.
// Round 14: the same columns and look as the preseason Prospect watch slide; each column its own sortable header.
const SEASON_PROSPECT_COLUMNS = [
  ["rank", [["rank", "#", "League consensus rank: the middle of all 30 teams' boards"]]],
  ["name", [["name", "Prospect"]]],
  ["from", [["from", "From", "School or club"]]],
  ["range", [["range", "League boards", "Where the 30 teams' boards put him: box the middle half, whiskers every team, white tick the consensus, gold dot your scouts"]]],
  ["yours", [["yours", "Your scouts", "Your scouts' board rank (talent only); the arrow is how far they differ from the league"]]],
  ["scouted", [["scouted", "Scouted", "How much of him your scouts have seen"]]],
];
const SEASON_PROSPECT_DESC_FIRST = new Set(["now", "potential", "scouted"]);

function seasonProspectSortValue(row, key) {
  const number = (value) => (value == null || value === "" || !Number.isFinite(Number(value)) ? null : Number(value));
  if (key === "name") return String(row.name || "") || null;
  if (key === "position") return typeof housePositionRank === "function" ? number(housePositionRank(row.position)) : String(row.position || "") || null;
  if (key === "height") { const inches = heightToInches(row.height); return Number.isFinite(inches) ? inches : null; }
  if (key === "rank") return number(row.consensusRank);
  if (key === "from") return String(row.sourceTeam || "") || null;
  if (key === "range") return number(row.draftRangeLow ?? row.consensusRank);
  if (key === "yours") return number(row.rank);
  if (key === "scouted") return number(row.scoutedPct ?? (row.confidence == null ? null : Number(row.confidence) * 100));
  return number(row[key]);
}

function sortSeasonProspectRows(rows, sort) {
  const direction = sort.direction === "desc" ? -1 : 1;
  const tieBreak = (row) => Number(row.consensusRank ?? row.rank) || Infinity;
  return [...rows].sort((a, b) => {
    const av = seasonProspectSortValue(a, sort.key), bv = seasonProspectSortValue(b, sort.key);
    if ((av == null) !== (bv == null)) return av == null ? 1 : -1;  // missing values always last
    const compared = av == null ? 0 : typeof av === "string" ? av.localeCompare(String(bv), undefined, {sensitivity:"base"}) : av - bv;
    return compared * direction || tieBreak(a) - tieBreak(b);
  });
}

function nextSeasonProspectSort(key) {
  const prior = state.dashboardProspectSort || {};
  if (prior.key === key) return {key, direction: prior.direction === "asc" ? "desc" : "asc"};
  return {key, direction: SEASON_PROSPECT_DESC_FIRST.has(key) ? "desc" : "asc"};
}

// Prospect ratings as coloured numbers on the game-wide rating colours (red low, blue high).
function seasonProspectRating(value) {
  const number = Number(value);
  if (value == null || value === "" || !Number.isFinite(number)) return "—";
  return `<strong class="season-prospect-rating" style="${playerRatingBarStyle(number)}">${number.toFixed(0)}</strong>`;
}

// Same-size greyscale face, bottom-aligned in the row; an empty frame keeps names lined up when there is no photo.
function seasonProspectFace(row) {
  const source = String(row?.prospect?.headshot_url || row?.headshot_url || "").trim();
  return `<span class="season-prospect-face" aria-hidden="true">${source ? `<img src="${escapeAttr(source)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" />` : ""}</span>`;
}

// One mini box plot per prospect on a shared rank scale (#1 at the left): the whiskers reach every team's best and
// worst rank for him, the box is where the middle half of teams rank him, the dark tick is the league consensus and
// the blue dot is your scouts' rank. Faint guide lines every 5 (or 10) ranks give the scale.
function seasonProspectRankRange(row, maxRank, sortKey) {
  const rank = (value) => (value == null || value === "" || !Number.isFinite(Number(value)) ? null : Number(value));
  const place = (value) => clampNumber((value - 1) / Math.max(1, maxRank - 1) * 100, 0, 100).toFixed(1);
  const consensus = rank(row.consensusRank), ours = rank(row.rank);
  const low = rank(row.draftRangeLow), high = rank(row.draftRangeHigh);
  const best = rank(row.consensusBest) ?? low, worst = rank(row.consensusWorst) ?? high;
  if (consensus == null && ours == null) return "—";
  const step = maxRank > 30 ? 10 : 5;
  const guides = Array.from({length: Math.floor((maxRank - 1) / step)}, (_unused, index) => `<i class="season-prospect-range-guide" style="left:${place((index + 1) * step)}%"></i>`).join("");
  const move = Number(row.rankChange);
  const title = [
    consensus != null ? `League consensus: #${consensus}` : "",
    low != null && high != null ? `Most teams (the middle half): #${low} to #${high}` : "",
    best != null && worst != null ? `Every team: #${best} to #${worst}` : "",
    ours != null ? `Your scouts: #${ours}${Number.isFinite(move) && move ? ` (${move > 0 ? "up" : "down"} ${Math.abs(move)} since last month)` : ""}` : "",
  ].filter(Boolean).join("\n");
  const shown = sortKey === "yours" ? ours : consensus ?? ours;
  return `<span class="season-prospect-range" title="${escapeAttr(title)}" aria-label="${escapeAttr(title.replace(/\n/g, ". "))}">
      <b class="season-prospect-range-number${sortKey === "yours" ? " is-ours" : ""}">${shown == null ? "—" : shown}</b>
      <span class="season-prospect-range-plot" aria-hidden="true">${guides}${best != null && worst != null ? `<i class="season-prospect-range-whisker" style="left:${place(best)}%;width:${(place(worst) - place(best)).toFixed(1)}%"></i>` : ""}${low != null && high != null ? `<i class="season-prospect-range-box" style="left:${place(low)}%;width:${(place(high) - place(low)).toFixed(1)}%"></i>` : ""}${consensus != null ? `<i class="season-prospect-range-median" style="left:${place(consensus)}%"></i>` : ""}${ours != null ? `<i class="season-prospect-range-ours" style="left:${place(ours)}%"></i>` : ""}</span>
    </span>`;
}

function seasonProspectsCard(options = {}) {
  const stored = state.dashboardProspectSort || {};
  const known = SEASON_PROSPECT_COLUMNS.some(([, keys]) => keys.some(([key]) => key === stored.key));
  const sort = known ? stored : {key:"rank", direction:"asc"};
  const sourceRows = options.rows || draftBoardRows(state.data.dashboardProspects || {});
  const sortedRows = sortSeasonProspectRows(sourceRows, sort);
  const rows = options.expanded ? sortedRows : sortedRows.slice(0, 6);
  const ranks = rows.flatMap((row) => [row.consensusWorst, row.draftRangeHigh, row.consensusRank, row.rank]).map(Number).filter(Number.isFinite);
  const maxRank = Math.max(10, Math.ceil(Math.max(1, ...ranks) / 5) * 5);
  const arrow = (key) => (sort.key === key ? `<i class="season-prospect-sort-arrow" aria-hidden="true">${sort.direction === "desc" ? "▼" : "▲"}</i>` : "");
  const head = SEASON_PROSPECT_COLUMNS.map(([column, keys]) => {
    const active = keys.some(([key]) => key === sort.key);
    const buttons = keys.map(([key, label, tip]) => `<button type="button" data-season-prospect-sort="${key}" aria-pressed="${sort.key === key}" title="${escapeAttr(`${tip || `Sort by ${label}`}${column === "range" ? `. Bar: whiskers every team, box the middle half, dark tick the league, blue dot your scouts (scale #1 to #${maxRank})` : ""}`)}">${key === "yours" ? `<i class="season-prospect-ours-key" aria-hidden="true"></i>` : ""}${escapeHtml(label)}${arrow(key)}</button>`).join(`<i class="season-prospect-sort-divider" aria-hidden="true">·</i>`);
    return `<th scope="col" class="season-prospect-col-${column}${active ? " is-sorted" : ""}" aria-sort="${active ? (sort.direction === "desc" ? "descending" : "ascending") : "none"}">${buttons}</th>`;
  }).join("");
  const sortedColumn = SEASON_PROSPECT_COLUMNS.find(([, keys]) => keys.some(([key]) => key === sort.key))?.[0];
  const cell = (column, content) => `<td class="season-prospect-col-${column}${column === sortedColumn ? " is-sorted" : ""}">${content}</td>`;
  return `<div class="season-prospect-list${options.expanded ? " season-prospect-list-expanded" : ""}">
      <table class="season-prospect-table" data-local-sort aria-label="Upcoming prospects">
        <thead><tr>${head}</tr></thead>
        <tbody>${rows.map((row) => {
          const confidence = clampNumber(Number(row.scoutedPct ?? Number(row.confidence || 0) * 100), 0, 100);
          return `<tr data-draft-prospect-card="${escapeAttr(row.id)}" title="Open scouting report for ${escapeAttr(row.name)}">
            ${cell("rank", escapeHtml(row.consensusRank ?? "—"))}
            ${cell("name", `<span class="season-prospect-name">${seasonProspectFace(row)}<span class="season-prospect-id"><b class="season-prospect-open">${escapeHtml(row.name || "Unknown")}</b><small>${escapeHtml([row.position, row.age === "" || row.age == null ? "" : row.age].filter(Boolean).join(" · "))}</small></span>${prospectInjuryMarkup(row.injuryReport, { compact: true })}</span>`)}
            ${cell("from", `<span class="ss-school">${prospectOriginMarkup(row.sourceTeam)}<span>${escapeHtml(row.sourceTeam || "—")}</span></span>`)}
            ${cell("range", seasonProspectRankRange(row, maxRank, "rank"))}
            ${cell("yours", (() => {
              if (row.rank == null || row.rank === "") return "—";
              const diff = Number(row.consensusRank) - Number(row.rank);
              const tag = Number.isFinite(diff) && diff ? `<small class="ss-rank-diff ${diff > 0 ? "is-up" : "is-down"}">${diff > 0 ? "▲" : "▼"}${Math.abs(diff)}</small>` : "";
              return `<span class="ss-your-rank"><b>#${escapeHtml(row.rank)}</b>${tag}</span>`;
            })())}
            ${cell("scouted", `<span class="ss-scouted" aria-label="Scouted ${confidence.toFixed(0)} percent"><i><b style="width:${confidence.toFixed(0)}%"></b></i><strong>${confidence.toFixed(0)}%</strong></span>`)}
          </tr>`;
        }).join("") || `<tr><td colspan="${SEASON_PROSPECT_COLUMNS.length}" class="empty">Prospect board unavailable.</td></tr>`}</tbody>
      </table>
      <div class="season-prospect-legend" aria-label="How to read League rank"><span><i class="is-box"></i>Middle half of teams</span><span><i class="is-whisker"></i>Every team</span><span><i class="is-median"></i>League consensus</span><span><i class="season-prospect-ours-key"></i>Your scouts</span></div>
    </div>`;
}

function regularSeasonProgressSlot(totalSlots = 26) {
  const currentText = String(state.home?.save?.current_date || "").slice(0, 10);
  const current = new Date(`${currentText || "2026-10-01"}T00:00:00Z`);
  if (Number.isNaN(current.getTime())) return 0;
  const year = current.getUTCFullYear();
  const month = current.getUTCMonth() + 1;
  const startYear = month >= 7 ? year : year - 1;
  const start = new Date(`${startYear}-10-01T00:00:00Z`);
  const elapsedWeeks = Math.floor(Math.max(0, current.getTime() - start.getTime()) / (7 * 24 * 60 * 60 * 1000));
  return clampNumber(elapsedWeeks, 0, Math.max(0, totalSlots - 1));
}

function seasonAwardsCard(editable) {
  const fields = Object.fromEntries((state.data.dashboardSummaryLeaders?.fields || []).map((field) => [field.key, field.leaders || []]));
  const races = [
    ["MVP", state.data.dashboardSummaryLeaders?.award_races?.MVP || (fields.points?.length ? fields.points : fields.overall || [])],
    ["DPOY", state.data.dashboardSummaryLeaders?.award_races?.DPOY || (fields.defense?.length ? fields.defense : fields.rim_deterrence || [])],
    ["ROTY", state.data.dashboardSummaryLeaders?.award_races?.ROTY || state.data.dashboardSummaryLeaders?.rookies || []],
  ];
  return `<div class="season-awards-grid">${races.map(([label, leaders]) => {
    const award = label.toLowerCase();
    const stats = SEASON_AWARD_STATS[label] || SEASON_AWARD_STATS.MVP;
    const [leader, ...chasers] = leaders.slice(0, 4);
    return `<section class="season-command-panel season-award-card" data-award="${award}" style="--award-stat-count:${stats.length}">
      <header class="season-award-head"><h3>${label}</h3></header>
      ${leader ? `<div class="season-award-race">
        ${seasonAwardLeader(leader, label, stats)}
        ${chasers.map((row, index) => seasonAwardChaser(row, index + 2, stats)).join("")}
      </div>` : `<div class="empty">No candidates yet.</div>`}
    </section>`;
  }).join("")}</div>`;
}

// Award race columns: [stat key, label, rating?]. Ratings show as coloured numbers; per-game stats need games played
// (an em dash before then). Stats come from the race rows (dashboard_metrics.award_watch_payload "stats").
const SEASON_AWARD_STATS = Object.freeze({
  MVP: [["overall", "OVR", true], ["points", "PTS"], ["rebounds", "REB"], ["assists", "AST"]],
  DPOY: [["defense", "DEF", true], ["steals", "STL"], ["blocks", "BLK"]],
  ROTY: [["overall", "OVR", true], ["points", "PTS"], ["rebounds", "REB"], ["assists", "AST"]],
});
// Real-world trophy pictures by award (data-trophy slot in the leader block). Empty until the files are added, e.g.
// mvp: "assets/trophies/mvp.png"; an award with no file listed shows no picture.
// The real trophies (NBA.com's 2022 trophy photos; see assets/trophies/CREDITS.md): Michael Jordan Trophy (MVP),
// Hakeem Olajuwon Trophy (DPOY), Wilt Chamberlain Trophy (Rookie of the Year).
const SEASON_AWARD_TROPHIES = Object.freeze({mvp: "/assets/trophies/mvp.png", dpoy: "/assets/trophies/dpoy.png", roty: "/assets/trophies/roty.png"});

function seasonAwardStatCells(row, stats, firstColumn) {
  const values = row.stats || {};
  return stats.map(([key, label, rating], index) => {
    const number = Number(values[key]);
    const known = values[key] != null && Number.isFinite(number);
    const text = known ? (rating ? number.toFixed(0) : number.toFixed(1)) : "—";
    return `<span class="season-award-stat" data-stat="${key}" title="${escapeAttr(label)}" style="grid-column:${firstColumn + index}"><b${known && rating ? ` class="season-award-rating" style="${playerRatingBarStyle(number)}"` : ""}>${text}</b></span>`;
  }).join("");
}

// Team as logo plus abbreviation; the rows below the leader use the logo alone (the card is narrow).
function seasonAwardTeam(row, {logoOnly = false} = {}) {
  const team = row.team_abbrev || teamLabel(row.team_id);
  const logo = teamLogoSrc(team);
  const label = logo && logoOnly ? "" : escapeHtml(team || "—");
  return `<span class="season-award-team" title="${escapeAttr(team || "")}">${logo ? `<img src="${escapeAttr(logo)}" alt="${logoOnly ? escapeAttr(team || "") : ""}" loading="lazy" decoding="async" />` : ""}${label}</span>`;
}

function seasonAwardFace(row, className) {
  const team = row.team_abbrev || teamLabel(row.team_id);
  const portrait = row.headshot_url || teamLogoSrc(team);
  return `<span class="${className}" aria-hidden="true">${portrait ? `<img class="${row.headshot_url ? "award-player-headshot" : "award-team-fallback"}" src="${escapeAttr(portrait)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" />` : ""}</span>`;
}

// The race leader: large face, name, team, the stat line (its labels head the rows below) and the weekly move.
function seasonAwardLeader(row, label, stats) {
  const award = label.toLowerCase();
  const trophy = SEASON_AWARD_TROPHIES[award];
  // Round 3: one centred composition: the trophy and the leader's headshot side by side, his name and team under
  // them, and his stat line centred under the name (its own small grid, not the chasers' columns).
  return `<button type="button" class="season-award-leader is-centred" data-dashboard-player-card="${escapeAttr(row.player_id)}">
      <span class="season-award-hero">${trophy ? `<span class="season-award-trophy" data-trophy="${award}" aria-hidden="true"><img src="${escapeAttr(trophy)}" alt="" loading="lazy" decoding="async" /></span>` : ""}${seasonAwardFace(row, "season-award-leader-face")}</span>
      <span class="season-award-leader-name"><b class="season-award-rank">${row.rank || 1}</b><strong>${escapeHtml(row.player_name)}</strong></span>
      ${seasonAwardTeam(row)}
      <span class="season-award-leader-stats" style="--leader-stats:${stats.length + 1}">
        ${stats.map(([key, statLabel]) => `<small class="season-award-stat-label" data-stat="${key}">${statLabel}</small>`).join("")}
        <small class="season-award-stat-label season-award-move-label">Change</small>
        ${seasonAwardStatCells(row, stats, 3)}
        ${seasonRankChange(row.rank_change, row.previous_week_rank ?? row.season_start_rank)}
      </span>
    </button>`;
}

// Second to fourth: one table-style row each (rank, small face, name, team, the same stats, the weekly move).
function seasonAwardChaser(row, rank, stats) {
  return `<button type="button" class="season-award-chaser" data-dashboard-player-card="${escapeAttr(row.player_id)}">
      <b class="season-award-rank">${row.rank || rank}</b>
      ${seasonAwardFace(row, "season-award-chaser-face")}
      <strong>${escapeHtml(row.player_name)}</strong>
      ${seasonAwardTeam(row, {logoOnly:true})}
      ${seasonAwardStatCells(row, stats, 5)}
      ${seasonRankChange(row.rank_change, row.previous_week_rank ?? row.season_start_rank)}
    </button>`;
}

function seasonRankChange(change, previousRank) {
  if (change == null || !Number.isFinite(Number(change))) return `<span class="season-rank-change neutral" title="Previous week's rank unavailable">—</span>`;
  const delta = Number(change);
  const label = delta > 0 ? `Up ${delta}` : delta < 0 ? `Down ${Math.abs(delta)}` : "Unchanged";
  return `<span class="season-rank-change ${delta > 0 ? "positive" : delta < 0 ? "negative" : "neutral"}" title="${label} from previous week's rank ${previousRank}" aria-label="${label} places since the previous week">${delta > 0 ? "↑" : delta < 0 ? "↓" : ""} ${Math.abs(delta)}</span>`;
}

const COACH_PORTRAIT_IDS = Array.from({length:6}, (_, index) => `coach-${String(index + 1).padStart(2, "0")}`);

function staffIdentity(row, index = 0) {
  return String(row.id || row.slot || row.role || index);
}

function coachPortraitAssignments(rows) {
  const roles = ["Head Coach", "Offensive Coordinator", "Defensive Coordinator", "Performance Lead", "Development Lead", "Scouting Lead"];
  const ordered = [...rows].sort((a, b) => {
    const order = (row) => { const index = roles.indexOf(staffRoleLabel(row.slot || row.role)); return index < 0 ? roles.length : index; };
    return order(a) - order(b);
  });
  const used = new Set();
  return new Map(ordered.map((row, index) => {
    const identity = staffIdentity(row, index);
    const start = [...identity].reduce((hash, character) => ((hash * 31) + character.charCodeAt(0)) >>> 0, 7) % COACH_PORTRAIT_IDS.length;
    let portraitIndex = start;
    if (used.size === COACH_PORTRAIT_IDS.length) used.clear();
    while (used.has(portraitIndex)) portraitIndex = (portraitIndex + 1) % COACH_PORTRAIT_IDS.length;
    used.add(portraitIndex);
    return [identity, COACH_PORTRAIT_IDS[portraitIndex]];
  }));
}

function coachPortraitMarkup(portraitId, extraClass = "") {
  if (!COACH_PORTRAIT_IDS.includes(portraitId)) return "";
  const path = `/assets/game-art/coaches/${portraitId}`;
  return `<span class="coach-portrait-art ${escapeAttr(extraClass)}" aria-hidden="true"><img class="coach-portrait-silver" src="${path}-silver.webp" alt="" decoding="async" draggable="false"><img class="coach-portrait-ink" src="${path}-ink.webp" alt="" decoding="async" draggable="false"></span>`;
}

// A staff member's own face: the real photo for a real head coach, otherwise a generated face of a fictional person
// or a stock photo (same gender as the name, the image for his or her age; faces.py). Saves made before faces existed fall back to the old shared coach art.
function staffPortraitMarkup(row, portraitId, extraClass = "") {
  const source = String(row?.headshot_url || "").trim();
  if (!source) return coachPortraitMarkup(portraitId, extraClass);
  const photo = row.headshot_source === "real_photo" || source.includes("/headshots/real/");
  return `<span class="coach-portrait-art staff-face-art${photo ? " is-photo" : ""} ${escapeAttr(extraClass)}" aria-hidden="true"><img class="coach-portrait-face" src="${escapeAttr(source)}" alt="" loading="lazy" decoding="async" draggable="false"></span>`;
}

function staffActionPermission(slot, permissions =state.data.staff?.team_report?.staff_action_permissions || state.data.dashboard?.staff_action_permissions || {}) {
  return permissions[slot] || {};
}

function staffActionAttributes(slot, action, permissions) {
  const permission = staffActionPermission(slot, permissions);
  return permission[`can_${action}`] === false ? `disabled title="${escapeAttr(permission[`${action}_reason`] || "Available next season.")}"` : "";
}

function seasonStaffRowMarkup(row, portraitId, {actions = false, candidate = false, permissions, order = 0} = {}) {
  const name = staffName(row);
  const role = staffRoleLabel(row.slot || row.role);
  const grade = Number(staffGrade(row) || 0);
  const salary = staffAav(row);
  const years = candidate ? row.asking_years || 2 : staffYears(row);
  const contract = `${salary ? money(salary) : "—"} × ${years || "—"}`;
  const personAction = candidate ? `data-staff-id="${escapeAttr(row.id)}"` : `data-dashboard-staff-card="${escapeAttr(staffIdentity(row))}"`;
  const actionAttributes = staffActionAttributes(row.slot || row.role, candidate ? "negotiate" : "fire", permissions);
  const roleRank = ["Head Coach", "Offensive Coordinator", "Defensive Coordinator", "Performance Lead", "Development Lead", "Scouting Lead"].indexOf(role);
  const sortData = `data-house-row data-house-order="${order}"${order % 2 ? " data-house-alt" : ""} data-sort-role="${roleRank < 0 ? 6 : roleRank}" data-sort-grade="${grade.toFixed(2)}" data-sort-contract="${salary ? Number(salary).toFixed(3) : ""}"`;
  return `<div class="season-staff-row${candidate ? " season-staff-candidate-row" : ""}" ${sortData}>
    <button type="button" class="season-staff-person" ${personAction} ${candidate && actionAttributes ? actionAttributes : `title="${escapeAttr(name)}"`} aria-label="${candidate ? "Negotiate with" : "Open coach card for"} ${escapeAttr(name)}">${staffPortraitMarkup(row, portraitId, "season-staff-portrait")}<span><strong title="${escapeAttr(name)}">${escapeHtml(name)}</strong><small title="${escapeAttr(role)}">${escapeHtml(role)}</small></span></button>
    <span class="season-staff-grade" aria-label="Grade ${grade.toFixed(0)}"><em>${grade.toFixed(0)}</em><i><b style="${performanceBarStyle(grade)}"></b></i></span>
    <span class="season-staff-contract"><strong>${escapeHtml(contract)}</strong></span>
    ${actions ? `<button type="button" class="season-staff-action" ${actionAttributes} ${candidate ? `data-staff-id="${escapeAttr(row.id)}"` : `data-fire-slot="${escapeAttr(row.slot || row.role)}"`}>${candidate ? "Negotiate" : "Fire"}</button>` : ""}
  </div>`;
}

function seasonStaffCard(dash, includeHeader = true, {actions = false, available = null} = {}) {
  const roles = ["Head Coach", "Offensive Coordinator", "Defensive Coordinator", "Performance Lead", "Development Lead", "Scouting Lead"];
  const rows = [...staffRows(dash)].sort((a, b) => {
    const order = (row) => { const index = roles.indexOf(staffRoleLabel(row.slot || row.role)); return index < 0 ? roles.length : index; };
    return order(a) - order(b);
  });
  const portraits = coachPortraitAssignments(rows);
  const payroll = staffBudgetSummary(rows, dash);
  const payrollLabel = payroll.max > 0 ? `${money(payroll.used)}/${money(payroll.max)}` : money(payroll.used);
  return `${includeHeader ? seasonPanelHeader("Coaching Staff") : ""}
    <div class="season-staff-summary" aria-label="Coaching staff overview">
      <span><strong>STAFF PAYROLL: ${escapeHtml(payrollLabel)}${available === null ? "" : ` · ${signedMoney(available)} available`}</strong></span>
    </div>
    <div class="season-staff-table" data-house-table="staff">
      <div class="season-staff-head" data-house-head>${houseHeader("staff", "role", "Staff Member", {title:"Sort by role, head coach first"})}${houseHeader("staff", "grade", "Grade")}${houseHeader("staff", "contract", "Contract", {title:"Sort by salary per season"})}${actions ? '<span aria-hidden="true"></span>' : ""}</div>
      ${rows.map((row, order) => seasonStaffRowMarkup(row, portraits.get(staffIdentity(row)), {actions, permissions:dash.staff_action_permissions, order})).join("") || `<div class="empty">No staff loaded.</div>`}
    </div>`;
}

function coachRatingRow(label, value, key, info = {}) {
  const average = info.averages?.[key];
  const display = value == null ? "—" : draftMetric(value);
  const description = info.descriptions?.[key] || "Impacts overall staff grade.";
  const difference = value == null || average == null ? null : Math.round((Number(value) - Number(average)) * 10) / 10;
  const comparison = difference == null ? "League average unavailable." : difference === 0
    ? "Equal to the league average for this role."
    : `${Math.abs(difference).toFixed(1)} rating points ${difference > 0 ? "above" : "below"} the league average for this role.`;
  const tooltip = `${label} — ${display} / 100\n${description}\n${comparison}${average == null ? "" : `\nLeague average: ${draftMetric(average)} · ${info.peer_count} active staff in this role.`}`;
  return `<div class="coach-trait-row" tabindex="0" data-draft-asset-tooltip="${escapeAttr(tooltip)}" aria-label="${escapeAttr(`${label}: ${display}`)}"><span>${escapeHtml(label)}</span><i aria-hidden="true"><b style="${performanceBarStyle(Number(value))}"></b>${average == null ? "" : `<em class="coach-league-average" style="left:${clampNumber(Number(average),0,100)}%"></em>`}</i><strong>${value == null ? "—" : draftMetric(value)}</strong></div>`;
}

function coachTraitRows(traits = {}, info = {}) {
  const entries = Object.entries(traits).filter(([, value]) => value != null && Number.isFinite(Number(value)));
  if (!entries.length) return `<div class="empty">No trait data.</div>`;
  return entries.map(([key, value]) => coachRatingRow(rowLabel(key), value, key, info)).join("");
}

function coachProfileCardMarkup(staff, portraitId, info = {}, options = {}) {
  const role = staffRoleLabel(staff.slot || staff.role);
  const salary = options.candidate ? Number(staff.asking_salary_millions || staffAav(staff)) : staffAav(staff);
  const years = options.candidate ? Number(staff.asking_years || staffYears(staff)) : staffYears(staff);
  return `<div class="coach-profile-card">
    <section class="coach-profile-identity">
      ${staffPortraitMarkup(staff, portraitId, "coach-profile-portrait")}
      <div class="coach-profile-bio">${options.context ? `<p class="coach-profile-context">${escapeHtml(options.context)}</p>` : ""}<h2>${escapeHtml(staffName(staff))}</h2><p>${escapeHtml(role)}</p></div>
      <dl class="coach-profile-contract" aria-label="${options.candidate ? "Candidate asking contract" : "Coach contract"}"><dt>${options.candidate ? "Asking contract" : "Contract"}</dt><dd>${salary ? `${money(salary)} × ${years || "—"}` : "—"}</dd></dl>
      <div class="coach-profile-overview" aria-label="Coach overview ratings">${coachRatingRow("Grade", staffGrade(staff), "grade", info)}${options.candidate ? (options.gradeChange == null ? "" : `<p class="coach-profile-grade-change"><strong>${options.gradeChange > 0 ? "+" : ""}${options.gradeChange.toFixed(1)}</strong> rating points vs current coach</p>`) : `${coachRatingRow("Morale", staff.morale, "morale", info)}${coachRatingRow("Job security", staff.job_security, "job_security", info)}`}</div>
    </section>
    <div class="coach-profile-panels">
      <section class="coach-profile-traits"><header>Coaching Traits</header><div>${coachTraitRows(staff.skill_traits || {}, info)}</div></section>
      <section class="coach-profile-traits"><header>Working Style</header><div>${coachTraitRows(staff.personality_traits || {}, info)}</div></section>
    </div>
  </div>`;
}

async function dashboardCoachCard(staffId) {
  const rows = staffRows(state.data.dashboard || {});
  const staff = rows.find((row, index) => staffIdentity(row, index) === String(staffId || ""));
  if (!staff) return showToast("That coach is no longer available.", true);
  const info = await action("coach_card", {...savePayload(), staff_id:staff.id});
  if (!info) return;
  const portraitId = coachPortraitAssignments(rows).get(staffIdentity(staff));
  await openPlayerCardOnClipboard({key:`coach:${staff.id}`, title:`${staffName(info.staff)} · Coach Card`, kind:"coach", body:coachProfileCardMarkup(info.staff, portraitId, info)});
}

function staffRoleLabel(role) {
  return ({
    head_coach: "Head Coach",
    offensive_coordinator: "Offensive Coordinator",
    defensive_coordinator: "Defensive Coordinator",
    development_lead: "Development Lead",
    performance_lead: "Performance Lead",
    scouting_lead: "Scouting Lead",
  })[String(role || "").toLowerCase()] || rowLabel(role || "Staff");
}

function seasonMinutesCard(rows, editable) {
  if (editable) ensureRotationDraft(rows);
  const assigned = (row) => isPlayerInjured(row.health) || playerIsResting(row)
    ? 0
    : Number(state.rotationDraft[row.id] ?? row.rotation_target_minutes ?? row.minutes_projection ?? 0);
  const sortedRows = [...rows].sort((left, right) => assigned(right) - assigned(left));
  const tools = editable ? `<div class="season-minutes-tools">${coachRestToggleMarkup("minutes-coach-rest")}<button type="button" class="season-minutes-reset-all" data-minute-reset-all aria-label="Reset all player minutes to automatic allocation" title="Every player back to the coach's automatic minutes">Reset all minutes</button></div>` : "";
  return `${seasonPanelHeader("Minutes + Availability", "", "availability")}${tools}
    <div class="season-minutes-table" style="--roster-count:${Math.max(1, rows.length)}" data-house-table="minutes">
      <div class="season-minutes-head" data-house-head>${houseHeader("minutes", "player", "Player", {className:"season-minutes-player-head"})}${houseHeader("minutes", "ovr", "OVR", {title:"Sort by overall rating (today's, for a player still rusty after an injury)"})}${houseHeader("minutes", "role", "Roles", {title:"Sort by offensive role"})}${houseHeader("minutes", "position", "Pos", {title:"Sort by position, point guard to center"})}${houseHeader("minutes", "height", "Height")}${houseHeader("minutes", "minutes", "Minutes", {title:"Sort by minutes. Sorting only reorders the list; it never changes anyone's minutes."})}${houseHeader("minutes", "fatigue", "Fatigue")}</div>
      ${sortedRows.map((row, index) => {
        const injured = isPlayerInjured(row.health);
        const resting = playerIsResting(row);
        const out = injured || resting;
        const injuryStatus = playerInjuryStatusMarkup(row) + playerRestMarkup(row);
        const overall = playerOverallToday(row);
        const roles = [row.primary_off_role, row.primary_def_role].map(role => role ? (PLAYER_ROLE_CHIPS[role] || [role])[0] : "");
        const minuteValue = out ? 0 : clampNumber(assigned(row), 0, 48);
        const rotationLocked = !out && (state.rotationLockedPlayerIds.has(row.id) || row.rotation_user_set);
        const position = String(row.position || "—").trim() || "—";
        const height = heightFromRow(row) || "—";
        return `<div class="season-minute-row${injured ? " injured" : ""}${resting ? " resting" : ""}" data-minute-row="${escapeAttr(row.id)}" data-house-row data-house-order="${index}"${index % 2 ? " data-house-alt" : ""} data-sort-player="${escapeAttr(row.name || "")}" data-sort-ovr="${overall ? overall.today.toFixed(1) : ""}" data-sort-role="${escapeAttr(roles[0] || roles[1] || "")}" data-sort-position="${housePositionRank(row.position)}" data-sort-height="${houseHeightInches(height)}">
          <button type="button" data-dashboard-player-card="${escapeAttr(row.id)}">${playerHeadshotMarkup(row, "roster-player-headshot")}<span class="season-minute-identity"><span class="season-minute-name-line"><span class="season-minute-player-name">${escapeHtml(row.name || "Unknown")}</span>${injuryStatus}</span></span><i class="season-row-motion" aria-hidden="true" hidden></i></button>
          <span class="season-minute-ovr-cell">${seasonMinuteOverall(row)}</span>
          <span class="season-minute-role-cell">${seasonMinuteRoleLine(row)}</span>
          <span class="season-minute-position" title="${escapeAttr(row.position || "Position unavailable")}">${escapeHtml(position)}</span>
          <span class="season-minute-height">${escapeHtml(height)}</span>
          <div class="season-minute-control"><label class="season-minute-slider${rotationLocked ? " user-locked" : ""}"><i><b class="season-minute-fill" style="width:${(minuteValue / 48 * 100).toFixed(2)}%"></b></i><input type="range" min="0" max="48" step="1" value="${minuteValue}" data-minute-player="${escapeAttr(row.id)}" aria-label="Minutes for ${escapeAttr(row.name || "player")}" ${editable && !out ? "" : "disabled"} /></label><span class="season-minute-number"><output data-minute-output="${escapeAttr(row.id)}">${minuteValue}</output>${playerRestButtonMarkup(row, editable)}</span><button type="button" class="season-minute-reset" data-minute-reset-player="${escapeAttr(row.id)}" aria-label="Reset ${escapeAttr(row.name || "player")} to automatic minutes" title="Reset to automatic minutes" ${rotationLocked && editable && !out ? "" : "hidden"} ${editable && !out ? "" : "disabled"}>×</button></div>
          ${seasonFatigueCell(row)}
        </div>`;
      }).join("") || `<div class="empty">No roster loaded.</div>`}
    </div>`;
}

// Minutes + Availability: who the player is at a glance, so minutes can be set without another window open (taste
// deck 2026-11-23): his overall as a coloured number and his offense / defense roles as one coloured pair.
function seasonMinuteOverall(row) {
  const overall = playerOverallToday(row);
  if (!overall) return "";
  return overallTodayMarkup(overall, "season-minute-ovr");
}

// A player's overall as the engine uses it today. Back from an injury he is rusty: the engine lowers his in-game
// ratings by `rust_penalty` for his first games back, so tables show today's number with the drop in small red
// beside it (taste deck round 2). A player who is out shows his healthy number: he doesn't play, so nothing is lowered.
// The engine's injury drop for one player, in rating points (the same for every rating): back from an injury and
// still rusty, today's `rust_penalty`; out injured, the rust he will carry when he returns (`return_penalty`: he
// doesn't play while out, so nothing is lowered until then).
function playerRatingDrop(row) {
  const health = row?.health;
  if (playerHasRust(health)) return {drop: Number(health.rust_penalty), out: false};
  if (health && isPlayerInjured(health) && Number(health.return_penalty) >= 0.1) return {drop: Number(health.return_penalty), out: true};
  return {drop: 0, out: false};
}

function ratingDropMarkup(row, label = "his ratings") {
  const {drop, out} = playerRatingDrop(row);
  if (!drop) return "";
  const title = out ? `Out injured: ${label} will be ${drop.toFixed(1)} lower for his first games back, while he shakes off the rust` : `${label[0].toUpperCase()}${label.slice(1)} ${drop.toFixed(1)} lower today, while he shakes off the rust from his injury`;
  return `<small class="rating-drop${out ? " is-on-return" : ""}" title="${escapeAttr(title)}">−${drop.toFixed(1)}</small>`;
}

function playerOverallToday(row) {
  const healthy = Number(rating(row, "overall"));
  if (!Number.isFinite(healthy)) return null;
  const {drop, out} = playerRatingDrop(row);
  return {healthy, drop, out, today: out ? healthy : healthy - drop};
}

function overallTodayMarkup({healthy, drop, out, today}, className = "") {
  if (!drop) return `<span class="${className} player-rating-bar" style="${playerRatingBarStyle(today)}" title="Overall ${today.toFixed(0)}"><em>${today.toFixed(0)}</em></span>`;
  if (out) return `<span class="${className} player-rating-bar has-rating-drop" style="${playerRatingBarStyle(today)}" title="${escapeAttr(`Overall ${today.toFixed(0)} healthy. Out injured; ${drop.toFixed(1)} lower for his first games back`)}"><em>${today.toFixed(0)}</em><small class="rating-drop is-on-return">−${drop.toFixed(1)}</small></span>`;
  const title = `Overall ${today.toFixed(0)} today: ${healthy.toFixed(0)} healthy, −${drop.toFixed(1)} while he shakes off the rust from his injury`;
  return `<span class="${className} player-rating-bar has-rating-drop" style="${playerRatingBarStyle(today)}" title="${escapeAttr(title)}"><em>${today.toFixed(0)}</em><small class="rating-drop">−${drop.toFixed(1)}</small></span>`;
}

function seasonMinuteRoleLine(row) {
  const pair = [row.primary_off_role, row.primary_def_role].filter(Boolean);
  if (!pair.length) return "";
  return `<span class="season-minute-roles">${pair.map((role) => {
    const [label, tone] = PLAYER_ROLE_CHIPS[role] || [role, "unknown"];
    return `<span class="role-text role-${escapeAttr(tone)}">${escapeHtml(label)}</span>`;
  }).join("")}</span>`;
}

function seasonMiniRating(value) {
  const score = clampNumber(Number(value || 0), 0, 99);
  return `<span class="season-mini-rating"><em>${score.toFixed(0)}</em><i><b style="${performanceBarStyle(score)}"></b></i></span>`;
}

// The engine's fatigue (0-100) as of today, straight from the health state; the tooltip adds the value his next game
// will use (fatigue at that tip-off, after the days off in between).
const FATIGUE_TIRED = 40;
const FATIGUE_VERY_TIRED = 60;

function seasonFatigueTone(fatigue) {
  return fatigue >= FATIGUE_VERY_TIRED ? "high" : fatigue >= FATIGUE_TIRED ? "medium" : "low";
}

function seasonFatigueTooltip(health = {}) {
  const fatigue = clampNumber(Number(health.fatigue || 0), 0, 100);
  const next = Number(health.fatigue_next);
  const nextText = Number.isFinite(next) && health.fatigue_next_date
    ? ` About ${next.toFixed(0)} at his next tip-off (${health.fatigue_next_date}): the value that game uses.`
    : "";
  return `Fatigue ${fatigue.toFixed(0)} / 100 today.${nextText}\n`
    + "Each game adds fatigue in proportion to his minutes (more for older players, poor stamina and road games); every day without a game clears about 40% of it.\n"
    + "A 36-minute starter on a normal schedule is near 50 right after a game and near 20 at the next tip-off; the second night of a back-to-back starts near 30.\n"
    + "Above the normal level at tip-off, his team tires a little and his injury risk rises a little; above 50 his own ratings drop too. Resting him for a game clears it fastest.";
}

function seasonFatigueCell(row) {
  const fatigue = clampNumber(Number(row.health?.fatigue || 0), 0, 100);
  const tone = seasonFatigueTone(fatigue);
  return `<span class="season-fatigue ${tone}" data-fatigue-value="${fatigue.toFixed(1)}" title="${escapeAttr(seasonFatigueTooltip(row.health || {}))}"><i><b style="width:${Math.max(fatigue > 0 ? 3 : 0, fatigue).toFixed(1)}%;background:${fatigue >= FATIGUE_VERY_TIRED ? "#c8434c" : fatigue >= FATIGUE_TIRED ? "#d09a2c" : "#4e9a6a"}"></b></i><em>${fatigue.toFixed(0)}</em></span>`;
}

const AWARD_MIN_GAMES = 65;

function closeRestMenu() {
  document.querySelectorAll(".season-rest-menu").forEach((menu) => menu.remove());
}

function openRestMenu(button) {
  const playerId = button.dataset.minuteRestPlayer;
  const row = rosterRows(state.data.dashboard || {}).find((item) => item.id === playerId);
  closeRestMenu();
  if (!row) return;
  const rest = row.health?.user_rest;
  const restingLeft = Number(rest?.games_left || 0);
  const reachable = row.award_games_max == null ? null : Number(row.award_games_max) + restingLeft;
  const option = (games) => {
    const after = reachable == null ? null : reachable - games;
    const underAward = after != null && after < AWARD_MIN_GAMES && reachable >= AWARD_MIN_GAMES;
    const note = underAward ? ` · under ${AWARD_MIN_GAMES} games` : "";
    const title = underAward ? `He could then play at most ${after} games this season: below the ${AWARD_MIN_GAMES} needed for season awards.` : `Sits his team's next ${restGamesLabel(games)}, then returns to his minutes.`;
    return `<button type="button" role="menuitem" data-rest-games="${games}" class="${underAward ? "award-warning" : ""}" title="${escapeAttr(title)}">${restGamesLabel(games)}${escapeHtml(note)}</button>`;
  };
  const awardNote = reachable == null ? "" : reachable >= AWARD_MIN_GAMES
    ? `Can still reach ${reachable} games (awards need ${AWARD_MIN_GAMES}).`
    : `Can reach at most ${reachable} games: already under the ${AWARD_MIN_GAMES} needed for awards.`;
  const menu = document.createElement("div");
  menu.className = "season-rest-menu";
  menu.setAttribute("role", "menu");
  menu.innerHTML = `<strong>${escapeHtml(rest ? `Resting: back in ${restGamesLabel(restingLeft)}` : `Rest ${row.name || "player"} for his team's next`)}</strong>
    ${[1, 2, 3, 4, 5].map(option).join("")}
    ${rest ? `<button type="button" role="menuitem" data-rest-games="0" class="cancel">Cancel rest</button>` : ""}
    <small>${escapeHtml(`His minutes target is kept; while he sits, the coach spreads his minutes.${awardNote ? ` ${awardNote}` : ""}`)}</small>`;
  document.body.append(menu);
  const box = button.getBoundingClientRect();
  menu.style.left = `${Math.max(4, Math.min(window.innerWidth - menu.offsetWidth - 4, box.right - menu.offsetWidth))}px`;
  menu.style.top = `${Math.min(window.innerHeight - menu.offsetHeight - 4, box.bottom + 2)}px`;
  menu.querySelectorAll("[data-rest-games]").forEach((item) => {
    item.addEventListener("click", async () => {
      closeRestMenu();
      await setPlayerRest(playerId, Number(item.dataset.restGames));
    });
  });
  setTimeout(() => document.addEventListener("click", function outside(event) {
    if (!menu.contains(event.target)) {
      closeRestMenu();
      document.removeEventListener("click", outside);
    }
  }), 0);
  menu.querySelector("[data-rest-games]")?.focus();
}

async function setPlayerRest(playerId, games) {
  if (state.simulationRunning || state.busy) return;
  try {
    const result = await action("set_player_rest", { ...savePayload(), player_id: playerId, games });
    if (result.status === "blocked") return showToast(result.reason || "Rest not set.", true);
    state.data.dashboard = result.dashboard;
    state.data.statusDashboard = result.dashboard;
    state.rotationDraft = {};
    state.rotationLockedPlayerIds.clear();
    if (state.view === "dashboard") renderDashboard();
    if (result.warning) showToast(result.warning, true);
    else showToast(games ? `Resting for ${restGamesLabel(games)}` : "Rest cancelled");
  } catch (error) {
    showToast(`Rest not set. ${error.message || String(error)}`, true);
  }
}

async function setCoachRestsPlayers(on) {
  try {
    const result = await action("update_game_settings", { ...savePayload(), settings: { coach_rests_players: Boolean(on) } });
    if (state.home) state.home.game_settings = result.game_settings;
    document.querySelectorAll("[data-coach-rest-toggle]").forEach((input) => { input.checked = Boolean(on); });
    showToast(on ? "Your coach will rest players by the AI coaches' rules" : "Your coach will only suggest rest (zZ)");
    if (state.view === "dashboard") renderDashboard();
  } catch (error) {
    showToast(`Setting not saved. ${error.message || String(error)}`, true);
  }
}

function wireCoachRestToggles(root = document) {
  root.querySelectorAll("[data-coach-rest-toggle]").forEach((input) => {
    if (input.dataset.coachRestWired) return;
    input.dataset.coachRestWired = "true";
    input.addEventListener("click", (event) => event.stopPropagation());
    input.addEventListener("change", () => setCoachRestsPlayers(input.checked));
  });
}

function seasonDevelopmentCard(rows) {
  const rosterIds = new Set(rows.map((row) => String(row.id || "")));
  const candidates = developmentPlayerCandidates(rows)
    .filter((candidate) => rosterIds.has(String(candidate.player_id)))
    .sort((left, right) => developmentMovementScore(right) - developmentMovementScore(left));
  const monthLabel = seasonDevelopmentMonthLabel(
    state.data?.dashboardTrends?.development?.latest_month || candidates[0]?.points?.at(-1)?.label,
  );
  state.devGraphCandidates = candidates;
  // Round 5: the Season and Month bars share one scale (the biggest change on the card), so their lengths compare.
  const deltaScale = Math.max(0.5, ...candidates.map((player) => {
    const values = (player.points || []).map((point) => Number(point.value)).filter(Number.isFinite);
    return values.length > 1 ? Math.max(Math.abs(values.at(-1) - values[0]), Math.abs(values.at(-1) - values.at(-2))) : 0;
  }));
  return `${seasonDevelopmentGraph(candidates)}<div class="season-development-list" style="--development-count:${Math.max(1, Math.min(9, candidates.length))};--development-total:${Math.max(1, candidates.length)}" data-house-table="development">
      <div class="season-development-head" data-house-head>${houseHeader("development", "player", "Player")}${houseHeader("development", "age", "Age")}${houseHeader("development", "movement", "Change", {title:"Change in overall rating this season (October to June, top bar) and in the latest month (bottom bar), from the game's actual rating changes. Sorts the biggest movers first, up or down."})}</div>
      ${candidates.map((player, index) => {
        const points = player.points || [];
        const values = points.map((point) => Number(point.value)).filter(Number.isFinite);
        const seasonDelta = values.length > 1 ? values.at(-1) - values[0] : 0;
        const monthDelta = values.length > 1 ? values.at(-1) - values.at(-2) : 0;
        const upside = clampNumber(Number(player.upside_remaining || 0), 0, 5);
        const age = Number.isFinite(Number(player.age)) ? Number(player.age).toFixed(0) : "—";
        const summary = `${player.name}, age ${age}: growth runway ${upside.toFixed(1)} of 5, rating change this season ${signedNumber(seasonDelta)}, ${monthLabel} ${signedNumber(monthDelta)}`;
        const runway = declineWatchApplies(player) ? Number(player.decline_watch.per_year) : upside;
        return `<button type="button" class="season-development-row" data-dashboard-player-card="${escapeAttr(player.player_id)}" aria-label="${escapeAttr(summary)}" data-house-row data-house-order="${index}"${index % 2 ? " data-house-alt" : ""} data-sort-player="${escapeAttr(player.name || "")}" data-sort-age="${escapeAttr(age === "—" ? "" : age)}" data-sort-runway="${Number.isFinite(runway) ? runway.toFixed(2) : ""}" data-sort-movement="${Math.abs(seasonDelta).toFixed(3)}" data-sort-season="${seasonDelta.toFixed(3)}" data-sort-month="${monthDelta.toFixed(3)}">
          <span class="season-development-player">${playerHeadshotMarkup(player, "roster-player-headshot")}<span class="season-development-name">${escapeHtml(player.name)}</span></span>
          <span class="season-development-age">${escapeHtml(age)}</span>
          <span class="season-development-metrics">
            ${seasonDevelopmentMetric("Season", seasonDelta, deltaScale)}
            ${seasonDevelopmentMetric(monthLabel, monthDelta, deltaScale)}
          </span>
        </button>`;
      }).join("") || `<div class="empty">Development history will appear after the first monthly update.</div>`}
    </div>`;
}

function setDevelopmentCardExpanded(expanded, card) {
  const panel = card?.matches?.('.season-development-panel') ? card : card?.querySelector?.('.season-development-panel');
  if (!panel) return;
  if (expanded && !panel.classList.contains('is-expanded')) {
    const row = panel.querySelector('.season-development-row');
    panel.style.setProperty('--development-row-height', `${row?.offsetHeight || 48}px`);
  }
  panel.classList.toggle('is-expanded', Boolean(expanded));
  if (!expanded) panel.querySelector('.season-development-list')?.scrollTo(0, 0);
}

// Player Development graph (taste deck round 3: a graph instead of a table). "This season": each picked player's
// overall month by month (the game's own monthly rating changes). "Next 3 seasons": the projection the extension page
// uses (extension_analysis.ability_projection: median line, faint scenario range). Each line ends in the player's
// headshot and name; a checkbox row picks who is drawn (the five with the most minutes to start).
const DEV_GRAPH_COLORS = ["#2563b0", "#c8563a", "#2f8a57", "#7a3fa8", "#b7791f", "#0f7c8c", "#a8434b", "#4b5b68"];
// The same hues lightened for the clear glass (each line and its name label at least 4.5:1 on the dark glass).
const DEV_GRAPH_COLORS_CLEAR = ["#86bfff", "#ffa585", "#7fdca2", "#cfa8f7", "#f2c46d", "#6fd6e0", "#ff9ea7", "#d3dde6"];
function seasonDevelopmentGraph(candidates) {
  const graph = (state.devGraph ||= {view: "season", picked: null});
  const minutesOf = (id) => Number(rosterRows(state.data.dashboard || {}).find((row) => String(row.id) === String(id))?.minutes_projection || 0);
  if (!graph.picked || !graph.picked.length || !graph.picked.every((id) => candidates.some((c) => String(c.player_id) === id))) {
    graph.picked = [...candidates].sort((a, b) => minutesOf(b.player_id) - minutesOf(a.player_id)).slice(0, 5).map((c) => String(c.player_id));
  }
  const future = graph.view === "future";
  const projections = state.data.devProjection?.projections || null;
  if (future && !projections && !state.devProjectionLoading) loadDevelopmentProjection();
  const picked = candidates.filter((c) => graph.picked.includes(String(c.player_id)));
  const palette = typeof clearGlass === "function" && clearGlass() ? DEV_GRAPH_COLORS_CLEAR : DEV_GRAPH_COLORS;
  const color = (id) => palette[graph.picked.indexOf(String(id)) % palette.length];
  const series = picked.map((c) => {
    const pts = future
      ? (projections?.[c.player_id] || []).map((p) => ({label: shortSeasonLabel(p.season), value: Number(p.overall), low: Number(p.low), high: Number(p.high)}))
      : (c.points || []).map((p) => ({label: seasonDevelopmentMonthLabel(p.label) || String(p.label || ""), value: Number(p.value)}));
    return {c, pts: pts.filter((p) => Number.isFinite(p.value))};
  }).filter((s) => s.pts.length);
  const W = 660, H = 210, left = 34, right = 178, top = 14, bottom = 26;
  // Short names: last name, with the first initial when two players share it (J. Williams, J. Williams → Jalen/Jaylin).
  const lastName = (c) => String(c.name || "").split(" ").slice(-1)[0];
  const shortName = (c) => candidates.filter((o) => lastName(o) === lastName(c)).length > 1 ? `${String(c.name || "").split(" ")[0]} ${lastName(c)}` : lastName(c);
  const labels = series.reduce((longest, s) => s.pts.length > longest.length ? s.pts.map((p) => p.label) : longest, []);
  const all = series.flatMap((s) => s.pts.flatMap((p) => [p.value, p.low ?? p.value, p.high ?? p.value]));
  // Round 4: the floor reaches at least 60 (lower for lower-rated players), so the scale doesn't jump as players are
  // picked and the band's low end is never clipped.
  const lo = Math.min(60, Math.floor((Math.min(...all, 100) - 2) / 5) * 5), hi = Math.ceil((Math.max(...all, 0) + 2) / 5) * 5;
  const x = (i) => left + (labels.length <= 1 ? 0 : i * (W - left - right) / (labels.length - 1));
  const y = (v) => top + (hi - v) / Math.max(1, hi - lo) * (H - top - bottom);
  const grid = [];
  for (let v = lo; v <= hi; v += 5) grid.push(`<line class="dev-grid" x1="${left}" x2="${W - right}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/><text class="dev-axis" x="${left - 6}" y="${(y(v) + 3.5).toFixed(1)}" text-anchor="end">${v}</text>`);
  // A light grid behind the lines: one rule every 5 points and one per month or season.
  labels.forEach((_, i) => grid.push(`<line class="dev-grid is-vertical" x1="${x(i).toFixed(1)}" x2="${x(i).toFixed(1)}" y1="${top}" y2="${(H - bottom).toFixed(1)}"/>`));
  const xLabels = labels.map((label, i) => `<text class="dev-axis" x="${x(i).toFixed(1)}" y="${H - 8}" text-anchor="middle">${escapeHtml(label)}</text>`).join("");
  // End labels: spread so names never overlap.
  const ends = series.map((s) => ({s, y: y(s.pts.at(-1).value)})).sort((a, b) => a.y - b.y);
  for (let k = 1; k < ends.length; k += 1) ends[k].y = Math.max(ends[k].y, ends[k - 1].y + 22);
  const lines = series.map((s) => {
    const id = s.c.player_id, col = color(id);
    const path = s.pts.map((p, i) => `${i ? "L" : "M"}${x(i).toFixed(1)},${y(p.value).toFixed(1)}`).join("");
    const band = future && s.pts.every((p) => Number.isFinite(p.low)) ? `<path class="dev-band" style="fill:${col}" d="${s.pts.map((p, i) => `${i ? "L" : "M"}${x(i).toFixed(1)},${y(p.high).toFixed(1)}`).join("")}${[...s.pts].reverse().map((p, k) => `L${x(s.pts.length - 1 - k).toFixed(1)},${y(p.low).toFixed(1)}`).join("")}Z"/>` : "";
    return `${band}<path class="dev-line${future ? " is-future" : ""}" style="stroke:${col}" d="${path}"/>${s.pts.map((p, i) => `<circle class="dev-dot" style="fill:${col}" cx="${x(i).toFixed(1)}" cy="${y(p.value).toFixed(1)}" r="2.6"><title>${escapeHtml(`${s.c.name}: ${p.label} ${p.value.toFixed(1)}`)}</title></circle>`).join("")}`;
  }).join("");
  const endLabels = ends.map(({s, y: ly}) => {
    const id = s.c.player_id, col = color(id), last = s.pts.at(-1);
    const shot = s.c.headshot_url ? `<image href="${escapeAttr(s.c.headshot_url)}" x="${W - right + 10}" y="${(ly - 11).toFixed(1)}" width="20" height="22" preserveAspectRatio="xMidYMax slice"/>` : "";
    return `<line class="dev-leader" style="stroke:${col}" x1="${(x(s.pts.length - 1) + 3).toFixed(1)}" y1="${y(last.value).toFixed(1)}" x2="${W - right + 8}" y2="${ly.toFixed(1)}"/>${shot}<text class="dev-name" x="${W - right + 34}" y="${(ly + 4).toFixed(1)}" style="fill:${col}">${escapeHtml(shortName(s.c))} ${last.value.toFixed(1)}</text>`;
  }).join("");
  const plot = series.length
    ? `<svg class="dev-plot" viewBox="0 0 ${W} ${H}" role="img" aria-label="${future ? "Projected overall, next three seasons" : "Overall this season, month by month"}">${grid.join("")}${xLabels}${lines}${endLabels}</svg>`
    : `<div class="dev-empty">${future && !projections ? "Loading projections…" : future ? "No projection available." : "The first monthly update will draw this season's lines."}</div>`;
  const picks = candidates.map((c) => {
    const on = graph.picked.includes(String(c.player_id));
    return `<label class="dev-pick${on ? " is-on" : ""}"${on ? ` style="--dev-color:${color(c.player_id)}"` : ""}><input type="checkbox" data-dev-pick="${escapeAttr(c.player_id)}" ${on ? "checked" : ""}/>${escapeHtml(shortName(c))}</label>`;
  }).join("");
  return `<section class="dev-graph" data-dev-graph>
      <div class="dev-graph-bar"><div class="dev-views" role="tablist"><button type="button" role="tab" data-dev-view="season" aria-selected="${!future}">This season</button><button type="button" role="tab" data-dev-view="future" aria-selected="${future}">Next 3 seasons</button></div><i class="g-info" tabindex="0" title="${future ? "Projected overall for the next three seasons: the line is the middle case, the shaded band the range of scenarios." : "Overall rating at each monthly update this season."}">i</i></div>
      ${plot}
      <div class="dev-picks">${picks}</div>
    </section>`;
}

async function loadDevelopmentProjection() {
  state.devProjectionLoading = true;
  try {
    state.data.devProjection = await action("development_projection", savePayload());
  } catch (error) {
    showToast(error.message || "Could not load projections.", true);
  } finally {
    state.devProjectionLoading = false;
    rerenderDevelopmentGraph();
  }
}

function rerenderDevelopmentGraph() {
  const node = document.querySelector("[data-dev-graph]");
  if (node && state.devGraphCandidates) node.outerHTML = seasonDevelopmentGraph(state.devGraphCandidates);
  window.CardBoard?.fitContent?.("development");
}

function seasonDevelopmentUpside(value) {
  const upside = clampNumber(Number(value || 0), 0, 5);
  const label = `Growth runway ${upside.toFixed(1)} of 5. Room this player has left to improve, from age, role and current level, on a 0-5 scale. Not a prediction of a future rating; 0 for most players 27 and older.`;
  return seasonDevelopmentOutlook(upside / 5, upside.toFixed(1), label, "up");
}

// Outlook (taste deck round 2, replacing the ring gauge): one short bar from a centre line. Room to grow fills to
// the right in green (share of the 0-5 runway scale); a veteran's expected decline fills to the left in red (share of
// a steep 2.5-a-year drop). The number beside it is the value itself.
function seasonDevelopmentOutlook(share, text, label, direction) {
  const width = (clampNumber(share, 0, 1) * 50).toFixed(1);
  return `<span class="season-development-upside season-development-outlook ${direction}" role="img" aria-label="${escapeAttr(label)}" title="${escapeAttr(label)}"><i><b style="width:${width}%"></b></i><strong>${text}</strong></span>`;
}

// Decline watch: veterans with no growth runway left show the engine's expected change in overall over the
// next 12 months if healthy (same monthly development model as the season, without its random noise).
const DECLINE_WATCH_TIP = "Decline watch: how much his hidden ratings are expected to drop over the next 12 months if he stays healthy, from the game's aging and development model (average per rating). An average, not a guarantee.";

function declineWatchApplies(row) {
  const value = Number(row?.decline_watch?.per_year);
  return Number.isFinite(value) && value <= -0.1 && Number(row?.upside_remaining || 0) <= 0;
}

function declineWatchDetail(decline) {
  return `${DECLINE_WATCH_TIP} Next year: ${Number(decline.per_year).toFixed(1)} per rating (athletic ${Number(decline.athletic).toFixed(1)}, skills ${Number(decline.skill).toFixed(1)}).`;
}

function seasonDevelopmentDecline(decline) {
  const amount = Number(decline.per_year);
  const label = declineWatchDetail(decline);
  return seasonDevelopmentOutlook(Math.abs(amount) / 2.5, `−${Math.abs(amount).toFixed(1)}`, label, "down");
}

function seasonDevelopmentMonthLabel(value) {
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const match = String(value || "").trim().match(/(?:^|[-/])(\d{1,2})$/);
  const month = Number(match?.[1]);
  return month >= 1 && month <= 12 ? months[month - 1] : "Month";
}

// scale: the OVR change that fills half the bar (real season changes are ~0-2 points, months ~0-0.5).
function seasonDevelopmentMetric(label, delta, scale = 2) {
  const amount = Number.isFinite(Number(delta)) ? Number(delta) : 0;
  const rounded = Number(amount.toFixed(1));
  const tone = rounded > 0 ? "positive" : rounded < 0 ? "negative" : "neutral";
  const width = clampNumber((Math.abs(amount) / Math.max(0.1, scale)) * 50, 0, 50);
  const direction = amount < 0 ? `right:50%` : `left:50%`;
  return `<span class="season-development-metric">
    <span class="season-development-period">${escapeHtml(label)}</span>
    <i class="season-development-diverging" aria-hidden="true"><b class="${tone}" style="width:${width}%;${direction}"></b></i>
    <strong class="${tone}">${signedNumber(amount)}</strong>
  </span>`;
}

function leagueActivitySubject(subject) {
  const portrait = subject.kind === "staff" ? staffPortraitMarkup(subject, coachPortraitAssignments([subject]).get(staffIdentity(subject)), "wire-staff-portrait") : playerHeadshotMarkup(subject, "wire-player-headshot");
  return `<div class="wire-subject ${subject.kind === "pick" ? "is-pick" : ""}"><div class="wire-subject-art">${portrait}${subject.kind === "pick" ? `<strong class="wire-pick-label">${escapeHtml(subject.season || "Draft")}<small>${subject.round ? `ROUND ${escapeHtml(subject.round)}` : "PICK"}</small></strong>` : ""}</div><span>${escapeHtml(subject.name || "")}</span></div>`;
}

function leagueActivityComment(event) {
  const paragraphs = event.activity_comments || [];
  return `<details class="wire-comments"><summary>Details <span>1 comment</span></summary><div class="wire-comment"><div class="wire-comment-author">League Insider <span>@leagueinsider</span></div>${paragraphs.map(text => `<p>${escapeHtml(text)}</p>`).join("") || `<p>${escapeHtml(event.headline || "No additional details available.")}</p>`}${(event.activity_groups || []).some(group => (group.subjects || []).some(subject => subject.kind === "player")) ? `<small class="wire-profile-note">Player profiles reflect the current season.</small>` : ""}</div></details>`;
}

function seasonLeagueWire(expanded = false) {
  const events = state.home?.league_events?.events || [];
  if (expanded) {
    const items = events.map((event) => {
      const normalized = normalizeLeagueEvent(event);
      const groups = event.activity_groups || [];
      const media = groups.some(group => group.subjects?.length) ? groups.map(group => {
        const subjects = group.subjects || [];
        const columns = subjects.length > 1 ? 2 : 1;
        return `<section class="wire-asset-group" style="--asset-columns:${columns};--asset-rows:${Math.max(1, Math.ceil(subjects.length / columns))}">${groups.length > 1 ? `<div class="wire-asset-team"><strong>${escapeHtml(group.team)}</strong><span>receives</span></div>` : ""}${teamLogoSrc(group.team) ? `<img class="wire-group-logo" src="${escapeAttr(teamLogoSrc(group.team))}" alt="${escapeAttr(group.team)}">` : ""}<div class="wire-subjects">${subjects.map(leagueActivitySubject).join("")}</div></section>`;
      }).join("") : normalized.teams.map(team => `<img class="wire-fallback-logo" src="${escapeAttr(teamLogoSrc(team))}" alt="${escapeAttr(team)}">`).join("");
      return `<article class="season-wire-post" data-league-event-id="${escapeAttr(event.id || "")}"><header class="wire-post-author"><span class="wire-reporter-avatar">LI</span><div><strong>League Insider</strong><span>@leagueinsider · <time datetime="${escapeAttr(normalized.date)}">${escapeHtml(formatDashboardShortDate(normalized.date) || normalized.date)}</time></span></div></header><div class="wire-post-type">${escapeHtml(rowLabel(normalized.kind))}</div><div class="wire-post-media ${groups.length > 1 ? "is-trade" : ""}">${media}</div><h3 class="wire-post-headline">${escapeHtml(event.activity_headline || normalized.text)}</h3>${leagueActivityComment(event)}</article>`;
    }).join("");
    return `<footer class="season-league-wire season-league-wire-expanded" aria-label="League activity"><div class="season-wire-activity-list">${items || `<div class="season-wire-activity-empty">No league activity to show.</div>`}</div></footer>`;
  }
  const items = events.slice(0, 12).map((event) => {
    const normalized = normalizeLeagueEvent(event);
    const marks = normalized.teams.map((team) => {
      const logo = teamLogoSrc(team);
      return logo ? `<img src="${escapeAttr(logo)}" alt="${escapeAttr(team)}" />` : "";
    }).join("");
    return `<span class="season-wire-item">${marks}<em>${escapeHtml(formatDashboardShortDate(normalized.date) || normalized.date)}</em><strong>${escapeHtml(normalized.text)}</strong></span>`;
  }).join("");
  return `<footer class="season-league-wire"><div class="season-wire-window"><div class="season-wire-track">${items || `<span class="season-wire-item"><strong>No recent league events.</strong></span>`}</div></div></footer>`;
}

function setLeagueWireCardExpanded(expanded, card) {
  if (!card) return false;
  const template = document.createElement("template");
  template.innerHTML = seasonLeagueWire(Boolean(expanded)).trim();
  const updated = template.content.firstElementChild;
  if (!updated) return false;
  card.className = updated.className;
  card.innerHTML = updated.innerHTML;
  return true;
}

function unifiedDashboardWorkspace(rows, dash, editable, readonlyClass) {
  if (state.dashboardWorkspace === "season") {
    return `<main class="unified-dashboard-workspace unified-season-workspace">
      <section class="unified-primary-panel calendar-card">${dashboardMonthCalendar()}</section>
      <aside class="unified-context-stack">
        <section class="unified-context-panel standings-card">${userConferenceStandings()}</section>
        <section class="unified-context-panel development-trend-card">${developmentTrendCard(rows)}</section>
      </aside>
    </main>`;
  }
  if (state.dashboardWorkspace === "league") {
    return `<main class="unified-dashboard-workspace unified-league-workspace">
      <section class="unified-primary-panel events-card">${leagueEventRotator(true)}</section>
      <aside class="unified-context-stack">
        <section class="unified-context-panel free-agent-market-card${readonlyClass}">${dashboardFreeAgentMarketCard(editable, 12, true)}</section>
        <section class="unified-context-panel standings-card">${userConferenceStandings()}</section>
      </aside>
    </main>`;
  }
  if (state.dashboardWorkspace === "office") {
    return `<main class="unified-dashboard-workspace unified-office-workspace">
      <section class="unified-primary-panel unified-office-staff">${staffDashboardCard(rows, dash, editable)}</section>
      <aside class="unified-context-stack">
        <section class="unified-context-panel draft-picks-card">${draftPicksCard()}</section>
        <section class="unified-context-panel unified-office-actions">${unifiedOfficeActions(editable)}</section>
      </aside>
    </main>`;
  }
  return `<main class="unified-dashboard-workspace unified-roster-workspace">
    <section class="unified-primary-panel player-summary-card">${dashboardPlayerSummaryTable(rows)}</section>
    <aside class="unified-team-intelligence" data-unified-team-intelligence>
      ${unifiedTeamIntelligence(rows, dash, editable)}
    </aside>
  </main>`;
}

function unifiedTeamIntelligence(rows, dash, editable) {
  const tabs = [["profile", "Profile"], ["starting", "Starting 5"], ["staff", "Staff"]];
  const selected = tabs.some(([key]) => key === state.dashboardIntelPanel) ? state.dashboardIntelPanel : "profile";
  let body = unifiedTeamProfile(dash);
  if (selected === "starting") body = startingFiveBlock(rows, editable);
  if (selected === "staff") body = staffDashboardCard(rows, dash, editable);
  return `<div class="unified-intelligence-tabs">${tabs.map(([key, label]) => `<button type="button" data-unified-intel-panel="${key}" class="${selected === key ? "active" : ""}">${label}</button>`).join("")}</div>
    <div class="unified-intelligence-body">${body}</div>`;
}

function unifiedTeamProfile(dash) {
  const identity = dash.team_identity || {};
  const metrics = identity.metrics || {};
  const ranks = identity.ranks || {};
  const count = identity.league_team_count || identity.team_count || 30;
  const cap = state.data.dashboardAssets?.cap || state.data.dashboardAssets?.cap_summary || {};
  const primary = [["OVR", metrics.overall, ranks.overall], ["OFF", metrics.offense, ranks.offense], ["DEF", metrics.defense, ranks.defense], ["DEPTH", metrics.depth, ranks.depth]];
  return `<section class="unified-profile-panel">
    <div class="unified-profile-metrics">${primary.map(([label, value, rank]) => `<div><span>${label}</span><strong>${Number(value || 0).toFixed(1)}</strong><small>#${escapeHtml(rank || count)}/${escapeHtml(count)}</small></div>`).join("")}</div>
    ${teamIdentityRadarChart(metrics, ranks, count)}
    ${cap && Object.keys(cap).length ? tradeCapStrip(cap) : ""}
  </section>`;
}

function unifiedOfficeActions(editable) {
  const disabled = editable ? "" : "disabled";
  const offerCount = Number(state.data.dashboardOffers?.offers?.length || 0);
  return `<div class="unified-office-action-grid">
    <button type="button" data-dashboard-trade="builder" ${disabled}>Trade Builder</button>
    <button type="button" data-dashboard-trade="finder" ${disabled}>Trade Finder</button>
    <button type="button" data-dashboard-player-finder ${disabled}>Player Finder</button>
    <button type="button" data-dashboard-view="draft" ${disabled}>Prospects</button>
    <button type="button" data-dashboard-offers ${disabled}>Trade Offers${offerCount ? ` (${offerCount})` : ""}</button>
    <button type="button" data-dashboard-settings ${disabled}>Settings</button>
  </div>`;
}

